INSERT INTO `wp_postmeta` VALUES (6607,1093,'_observaciones','<strong>Descripción del trámite:</strong>\n\nPresentarse en ventanilla de la Dirección de Catastro.\n\n<strong>Documento que se obtiene:</strong>\n\nCertificado de número de puerta.\n\n<strong>¿Quién lo puede realizar?</strong>\n\nContribuyente y profesionales en general.\n\n<strong>¿Cómo recibo el resultado del trámite?</strong>\n\nSe entrega en el momento el certificado de número en puerta.\n\n<strong>Costo del trámite:</strong>\n\nGratuito.');
