INSERT INTO `wp_postmeta` VALUES (7312,1139,'_presentacion_del_tramite','Este permiso es para todo comercio habilitado que desea realizar ocupación en la pública a través de Mesas - Sillas - Cajones\n<ol>\n 	<li>Diríjase a la Dirección General de Habilitaciones para obtener los requisitos necesarios para el inicio del trámite.</li>\n 	<li>Una vez reunida toda la información y documentación requerida, preséntala en Mesa de Entrada del municipio para la creación del expediente.</li>\n 	<li>El expediente será derivado nuevamente a la Dirección de Habilitaciones para finalizar el trámite.</li>\n 	<li>Al concluir el proceso, se le entregará un recibo que avala la ocupación de la vía pública.</li>\n</ol>\n&nbsp;');
INSERT INTO `wp_postmeta` VALUES (7313,1139,'_requisitos','<ul>\n 	<li>Toda persona física mayor de 18 años que sea comerciante.</li>\n 	<li>Nota solicitando la autorización para colocar elementos en la vía pública (mesas, sombrillas, bancos, barandas, toldos canadienses, carteles, decks, etc.), detallando medidas de alto, ancho y otras especificaciones, con firma, aclaración y teléfono del titular.</li>\n 	<li>Si posee luces fuera del local, presentar <strong>Certificado de Electricista Matriculado</strong> que detalle la instalación.</li>\n 	<li>Fotocopia de la habilitación del comercio.</li>\n</ul>\n<strong>Según el tipo de solicitante:</strong>\n<ul>\n 	<li><strong>Comercio unipersonal:</strong> Fotocopia del DNI del titular.</li>\n 	<li><strong>Sociedad:</strong> Estatuto, última acta de directorio y fotocopia del DNI del socio/gerente.</li>\n 	<li><strong>Apoderado:</strong> Poder legal y fotocopia del DNI del apoderado.</li>\n 	<li>Foto amplia del comercio y la vereda.</li>\n</ul>');
