INSERT INTO `wp_postmeta` VALUES (7663,1248,'_requisitos','<ul>\n 	<li>Tener un emprendimiento con mínimo 8 meses de antigüedad.</li>\n 	<li>Tener domicilio fiscal en el partido de san miguel</li>\n 	<li>Tener activo el monotributo e IIBB, o estar en trámite.</li>\n 	<li>Llenar la planilla de aplicación (Se hace de manera presencial)</li>\n</ul>');
