INSERT INTO `wp_postmeta` VALUES (7987,1266,'_horarios_de_atencion','<ul>\n 	<li>Lunes a Viernes de 8 a 14 hs.</li>\n 	<li>Teléfono: 6091-7185 int. 6812</li>\n</ul>');
