INSERT INTO `wp_postmeta` VALUES (8037,1268,'_presentacion_del_tramite','División de lote según plano original para la creación de parcelas catastralmente independientes, con apertura de Partidas (Provincia- MSM) a partir de Acciones Posesorias en el marco de la Ley 24.374');
INSERT INTO `wp_postmeta` VALUES (8038,1268,'_requisitos','<ol>\n 	<li>No debe poseer otro inmueble, el bien requerido debe ser tu vivienda única, familiar y permanente</li>\n 	<li>Exposición Civil (MSM/ Negativa de ANSES)</li>\n 	<li>Boleto de compra/ venta</li>\n 	<li>N.I. de los titulares y el grupo familiar conviviente con los domicilios actualizados</li>\n 	<li>U.I.L/ C.U.I.T. de los titulares</li>\n 	<li>Acta de matrimonio de los solicitantes (si son casados)</li>\n 	<li>Servicios de luz, gas, teléfono, boletas oficiales, etc., que demuestren posesión efectiva y permanente</li>\n 	<li>Firma del Convenio Marco MSM</li>\n</ol>');
