INSERT INTO `wp_postmeta` VALUES (8041,1268,'_respaldo_legal','<ul>\n 	<li>Regularización Dominial en el Marco de Interés Social</li>\n 	<li>Ordenanza 000007/2020</li>\n 	<li>Ley 24.374</li>\n</ul>');
INSERT INTO `wp_postmeta` VALUES (8042,1268,'_observaciones','<strong>Descripción del trámite:</strong>\n\nPresentarse en Oficina 19 de Subsecretaría de Tierras, Vivienda y Urbanismo.\n\n<strong>Documento que se obtiene:</strong>\n\nAprobación definitiva del plano de Mensura con la división de la parcela y apertura de partidas.\n\n<strong>¿Quién lo puede realizar?:</strong>\n\nVecinos de San Miguel que tengan la posesión de su vivienda sobre un porcentual de suelo donde haya que realizar la división de lote, según plano original, para la creación de parcelas catastralmente independiente con las correspondientes partidas inmobiliarias.\n\n<strong>¿Cómo recibo el resultado del trámite?</strong>\n\nMediante teléfono, correo electrónico y notificación al domicilio para retirar el mismo.\n\n<strong>Costo del trámite:</strong>\n\nPago único de tasa fija sobre derechos de Mensura Social-no subvencionable- (Recursos Tributarios-MSM), abonar una vez generada la nueva parcela, <a href=\"/boletin-oficial/\">según fiscal y tarifaria vigente</a>.');
INSERT INTO `wp_postmeta` VALUES (8043,1268,'_lugar_de_atencion','Subsecretaria de Tierras, Vivienda y Urbanismo Social, Oficina 19 dentro del edificio municipal (Sarmiento 1551, San Miguel)');
