INSERT INTO `wp_postmeta` VALUES (17273,1000,'_observaciones','<strong>Documento obtenido:</strong>\n\nCarnet de socio.\n\n<strong>Descripción del trámite:</strong>\n\nPresentarse en la Biblioteca Municipal con la documentación requerida.\n\n<strong>¿Quién lo puede realizar?:</strong>\n\nPersonas mayores de 16 años\n\n<strong>Costo del trámite:</strong>\n\n$ 550');
