INSERT INTO `wp_postmeta` VALUES (18338,5067,'_presentacion_del_tramite','<span style=\"font-weight: 400\">La </span><b>firma digital</b><span style=\"font-weight: 400\"> permite garantizar la identidad de quien firma un documento electrónico y asegurar que el contenido no haya sido modificado. Tiene la misma validez legal que una firma manuscrita y puede utilizarse en gestiones públicas o privadas.</span>\n\n<span style=\"font-weight: 400\">El trámite se realiza mediante la </span><b>Autoridad Certificante de la Oficina Nacional de Tecnologías de la Información (ONTI)</b><span style=\"font-weight: 400\"> y la </span><b>Municipalidad de San Miguel</b><span style=\"font-weight: 400\"> actúa como </span><b>Autoridad de Registro Local</b><span style=\"font-weight: 400\">.</span>\n\n<b>Importante:</b><span style=\"font-weight: 400\"> El trámite es totalmente </span><b>gratuito</b><span style=\"font-weight: 400\">.</span>\n<h5><b>¿A quién está dirigido?</b></h5>\n<span style=\"font-weight: 400\">A personas que necesiten firmar digitalmente documentos oficiales, administrativos o personales utilizando un </span><b>dispositivo criptográfico (token)</b><span style=\"font-weight: 400\">.</span>');
