INSERT INTO `wp_postmeta` VALUES (18881,1111,'_vigencia_del_documento_obtenido','<ul>\n 	<li>El certificado de eximición entregado es un documento que acredita la eximición de la tasa por el año/s solicitado/s</li>\n</ul>');
