INSERT INTO `wp_postmeta` VALUES (19383,1246,'_presentacion_del_tramite','<div class=\"bg-tramite\">PRESENTACIÓN DEL TRÁMITE</div>\n<div class=\"bg-secretaria border-table\">\n<p class=\"bg-secretaria border-table\">Para conservar la condición de exento de IIBB se deberá realizar de manera anual una Declaración Jurada. Esta permite cumplir con el requisito y seguir estando exento del pago de dicho tributo.</p>\n\n</div>');
