INSERT INTO `wp_postmeta` VALUES (26611,5067,'_duracion_del_tramite','La actualización de datos en el Token tiene una duración aproximada de 20 minutos.');
INSERT INTO `wp_postmeta` VALUES (26612,5067,'_vigencia_del_documento_obtenido','La Firma Digital y su actualización, tienen una vigencia de dos años.');
