INSERT INTO `wp_postmeta` VALUES (26822,1091,'_respaldo_legal','<ol>\n 	<li>Ordenanza Fiscal</li>\n 	<li>Tarifaria vigente.</li>\n 	<li>Código Civil</li>\n</ol>');
INSERT INTO `wp_postmeta` VALUES (26823,1091,'_observaciones','Las Partidas Municipales deben corresponderse con la parcela indicada en la Escritura de referencia, debe poseer “Vigencia administrativa”, es decir, si la parcela sufrió modificaciones por planos (Geodesia o Propiedad Horizontal), éste deberá estar empadronado en el municipio, con Partidas Municipales vigente emitiendo individualmente para realizar dicho trámite.\n\n<strong>Descripción del trámite:</strong>\n<ol>\n 	<li>Ingresar a <a href=\"https://ventanillaunica.msm.gov.ar/Account/Login\" target=\"_blank\" rel=\"noopener\">Portal de Trámites.</a></li>\n 	<li>Iniciar sesión con clave AFIP/ANSES y seguir los pasos.</li>\n</ol>\n<strong>Documento que se obtiene:</strong>\n\nTSM a nombre del propietario.\n\n<strong>¿Quién lo puede realizar?:</strong>\n\nTodos los vecinos propietarios de un inmueble que no hayan actualizado la titularidad de la TSM.\n\n<strong>Costo del trámite:</strong>\n\n<a href=\"/boletin-oficial/\">SEGÚN ORDENANZA TARIFARIA Y FISCAL VIGENTE</a>\n\n&nbsp;');
