INSERT INTO `wp_postmeta` VALUES (26837,1092,'_requisitos','<ol>\n 	<li>Formulario A901 – 903 o el que corresponda al tipo de propiedad.</li>\n 	<li>Cédula Catastral de ARBA con superficie edificada en parcela (valuación actualizada).</li>\n 	<li>En caso de unidades funcionales, subdivisiones o unificaciones, los planos deberán contar con vigencia administrativa (excluyente).</li>\n 	<li>El escribano deberá estar registrado en la base de datos del municipio.</li>\n</ol>');
