INSERT INTO `wp_postmeta` VALUES (26853,1092,'observaciones','Descripción del trámite:\n\n 	Ingresar a Portal de Trámites.\n 	Iniciar sesión con clave AFIP/ANSES y seguir los pasos.\n\nDocumento que se obtiene:\n\nCertificado informado por la Dirección de Recursos Tributario la deuda de la TSM\n\n¿Quién lo puede realizar?:\n\nEscribanías\n\n¿Cómo recibo el resultado del trámite?:\n\nEl titular recibirá los resultados en forma de documentos adjuntos a través de la web.\n\nCosto del trámite:\n\nSEGÚN ORDENANZA TARIFARIA Y FISCAL VIGENTE\n\n&nbsp;');
INSERT INTO `wp_postmeta` VALUES (26854,1093,'_presentacion_del_tramite','El objetivo del trámite es asignar un número de puerta a una parcela. Asimismo, corroborar y certificar los números de puerta existentes.');
