INSERT INTO `wp_postmeta` VALUES (26895,1095,'_observaciones','<strong>Descripción del trámite:</strong>\n\nAcercarse a la Escuela Primaria N°1 (Av. Balbín 1254) con la documentación solicitada.\n\n<strong>Documento que se obtiene:</strong>\n\nConstancia de Inscripción.\n\n<strong>¿Quién lo puede realizar?:</strong>\n\nDestinado a adultos mayores de 18 años, sin límite de edad.\n\n<strong>¿Cómo reciboe el resultado del trámite?:</strong>\n\nConfirmación vía mail.\n\n<strong>Costo del trámite:</strong>\n\nSin costo.');
