INSERT INTO `wp_postmeta` VALUES (27324,1136,'_presentacion_del_tramite','El <strong>Cambio de Rubro</strong> se realiza cuando existe una modificación total del rubro comercial habilitado.\n\n<strong>DOCUMENTO QUE SE OBTIENE:</strong>\n<ul>\n 	<li>Resolución de Habilitación.</li>\n 	<li>Certificado de Habilitación Comercial</li>\n</ul>\n<h3><strong>PASOS A SEGUIR:</strong></h3>\n<ol>\n 	<li><strong>Presentar la documentación completa:</strong> Subir los archivos requeridos al <a href=\"https://ventanillaunica.msm.gov.ar/PortalTramites/Account/Login\">Portal de Trámites.</a></li>\n 	<li><strong>Evaluación técnico-administrativa:</strong> Se analiza la documentación presentada.</li>\n 	<li><strong>Coordinación de inspección:</strong> Se acuerda una <strong>Inspección Final</strong> con el titular.</li>\n 	<li><strong>Creación de cuentas y liquidaciones:</strong>\n<ul>\n 	<li>Para <strong>rubros de impacto bajo</strong>, se crea la cuenta de Seguridad e Higiene y el trámite se deriva al área de Tasas Comerciales.</li>\n 	<li>Para <strong>rubros de impacto alto</strong>, se genera la cuenta comercial y se cobra el Derecho de Habilitación antes de continuar con la Resolución de Habilitación.</li>\n</ul>\n</li>\n 	<li><strong>Pago de Seguridad e Higiene:</strong> El titular recibirá la primera boleta de pago en la Ventanilla Única y deberá registrarse en el portal de Autogestión para continuar con los pagos mensuales.</li>\n 	<li><strong>Finalización del trámite:</strong></li>\n</ol>\n<ul>\n 	<li style=\"list-style-type: none\"></li>\n</ul>\n<ul>\n 	<li style=\"list-style-type: none\">\n<ul>\n 	<li>Para rubros de impacto bajo: El Certificado de Habilitación estará disponible una vez realizado el pago inicial.</li>\n 	<li>Para rubros de impacto alto: Después de completar la Resolución de Habilitación, se informará cuándo retirar el Certificado de Habilitación.</li>\n</ul>\n</li>\n</ul>');
INSERT INTO `wp_postmeta` VALUES (27325,1136,'_requisitos','<ul>\n 	<li>Personas físicas mayores de 18 años.</li>\n 	<li>Personas jurídicas que deseen cambiar el rubro de un comercio o servicio en el Partido de San Miguel.</li>\n</ul>\n<ol>\n 	<li><strong>Documentación básica:</strong></li>\n</ol>\n<ol>\n 	<li style=\"list-style-type: none\">\n<ul>\n 	<li>Certificado de Factibilidad Aprobada o Resolución de Radicación.</li>\n 	<li>Solicitud de Habilitación (declaración jurada).</li>\n 	<li>Formulario de Activos Fijos.</li>\n 	<li>Estatuto de Sociedad (para personas jurídicas).</li>\n 	<li>Poder legal (si aplica).</li>\n 	<li>Contrato de Locación o Comodato Timbrado.</li>\n 	<li>Escritura o Informe de Dominio.</li>\n 	<li>Constancia de inscripción en AFIP/ARCA con actividad y domicilio comercial actualizados.</li>\n 	<li>Constancia de inscripción en Ingresos Brutos (si aplica).</li>\n 	<li>Plano de Obra Aprobado con Destino Comercial.</li>\n 	<li>Certificado o Resolución de Habilitación anterior.</li>\n 	<li>Declaración Jurada Anual de la Tasa de Seguridad e Higiene (últimos 5 años).</li>\n 	<li>Estado de Deuda o Libre Deuda de la Tasa de Seguridad e Higiene.</li>\n</ul>\n</li>\n</ol>\n2. <strong>Documentación adicional (si aplica):</strong>\n<ul>\n 	<li style=\"list-style-type: none\">\n<ul>\n 	<li>Para superficies comerciales ≥200 m² o rubros de impacto alto:\n<ul>\n 	<li>Plano e Informe Antisiniestral aprobado por la Dirección General de Bomberos.</li>\n 	<li>Certificado de Aptitud de Instalaciones Eléctricas (C.A.I.E).</li>\n</ul>\n</li>\n</ul>\n</li>\n</ul>');
