INSERT INTO `wp_posts` VALUES (1111,1,'2024-11-19 11:23:28','2024-11-19 11:23:28','Para iniciar el trámite debe completar los formularios de solicitud para eximición de la tasa por inspección de seguridad e higiene (TISH) y de ofrecimiento de becas, instalaciones y/o cursos de capacitación.','Exención de tasa por inspección de Seguridad e Higiene','','publish','open','open','','exencion-de-tasa-por-inspeccion-de-seguridad-e-higiene-hacienda-tsh','','','2024-11-19 11:23:28','2024-11-19 11:23:28','',0,'http://msm-dev.local/guia-tramites/%area_tramite%/exencion-de-tasa-por-inspeccion-de-seguridad-e-higiene-hacienda-tsh/',0,'tramite','',0);
