INSERT INTO `wp_posts` VALUES (1115,1,'2024-11-19 11:23:29','2024-11-19 11:23:29','Para realizar cualquier tipo de trámite relacionado a la habilitación, se debe presentar una DDJJ Anual Informativa','Presentación de Declaración Jurada','','publish','open','open','','presentacion-de-declaracion-jurada-anual-2','','','2024-11-19 11:23:29','2024-11-19 11:23:29','',0,'http://msm-dev.local/guia-tramites/%area_tramite%/presentacion-de-declaracion-jurada-anual-2/',0,'tramite','',0);
