INSERT INTO `wp_posts` VALUES (1138,1,'2024-12-10 10:19:41','2024-12-10 13:19:41','Este trámite es para regularizar todas y cada uno de las ventas que se realicen en la vía pública.','Permiso para la venta ambulante','','publish','closed','closed','','permiso-de-venta-ambulante','','','2024-12-10 10:19:41','2024-12-10 13:19:41','',0,'https://www-dev.msm.gov.ar/?post_type=tramite&amp;p=1138',0,'tramite','',0);
