INSERT INTO `wp_posts` VALUES (1140,1,'2024-12-10 10:42:20','2024-12-10 13:42:20','Este permiso se encuentra destinado a todos los comercios habilitados que deseen publicitar y/o promocionar su comercio.','Permiso de publicidad y propaganda (cartelería y toldos)','','publish','closed','closed','','permiso-de-publicidad-y-propaganda','','','2024-12-10 10:42:20','2024-12-10 13:42:20','',0,'https://www-dev.msm.gov.ar/?post_type=tramite&amp;p=1140',0,'tramite','',0);
INSERT INTO `wp_posts` VALUES (1142,1,'2024-12-10 14:06:13','2024-12-10 17:06:13','Destinado a todo comercio habilitado y destinado a aquellos rubros que contemplen espectáculos públicos.','Permiso de espectáculos públicos','','publish','closed','closed','','permiso-de-espectaculos-publicos','','','2024-12-10 14:06:13','2024-12-10 17:06:13','',0,'https://www-dev.msm.gov.ar/?post_type=tramite&amp;p=1142',0,'tramite','',0);
