INSERT INTO `wp_posts` VALUES (1265,1,'2025-01-20 13:12:57','2025-01-20 16:12:57','Podrá ser presencial u online, iniciando el expediente se designará fecha para una audiencia de conciliación (opcional: presencial o vía zoom)','Denuncia en Defensa al Consumidor','','publish','closed','closed','','denuncia-en-defensa-al-consumidor','','','2025-01-20 13:12:57','2025-01-20 16:12:57','',0,'https://www-dev.msm.gov.ar/?post_type=tramite&amp;p=1265',0,'tramite','',0);
