INSERT INTO `wp_posts` VALUES (2539,1,'2025-02-26 11:01:22','2025-02-26 14:01:22','<h3>Si tu vocación es cuidar, nosotros te damos la formación científica que necesitas…</h3>\n&nbsp;\n<ul>\n	<li>Certificado intermedio (1 año): “Auxiliar de Enfermería” con matrícula</li>\n	<li>Titulo final: (3 años): “Enfermero Profesional”  Con matrícula y certificado Nacional de Pasantías/Residencias.</li>\n</ul>\n\n<hr />\n<p align=\"center\"><b>30 AÑOS FORMANDO PROFESIONALES DE LA SALUD.</b></p>\n<p align=\"center\"><b>INSCRIPCIÓN ABIERTA A PARTIR DEL 4 DE NOVIEMBRE DEL 2014</b></p>\n<p align=\"center\"><b>INSTITUTO SUPERIOR DE </b><b>FORMACIÓN TÉCNICA </b><b>“SAN MIGUEL ARCÁNGEL”</b></p>\n<p align=\"center\"><b>ESCUELA DE ENFERMERÍA</b></p>\n<p align=\"center\"><b>DIPREGEP N° 6392</b><b> </b></p>\n\n\n<hr />\n\n&nbsp;','Escuela de enfermería','','publish','open','open','','escuela-de-enfermeria','','','2025-02-26 11:01:22','2025-02-26 14:01:22','',0,'http://msm-dev.local/centros-salud/escuela-de-enfermeria/',0,'centros_salud','',0);
