INSERT INTO `wp_posts` VALUES (2774,1,'2025-05-17 22:19:20','2025-05-17 22:19:20','<h4></h4>\n<h4><b>Estudios que se realizan:</b></h4>\n<ul>\n 	<li>Ergometría</li>\n 	<li>Holter</li>\n 	<li>Presurometría</li>\n 	<li>Ecocardiograma</li>\n 	<li>Electrocardiograma</li>\n 	<li>Tomografías computadas*</li>\n 	<li>Tomografías Multislice con y sin contraste: cerebral, cuello, macizo, craneofacial, oídos, tórax, abdominopelviana, columna, miembros.</li>\n 	<li>Radiología, placas simples</li>\n 	<li>Estudios contrastados</li>\n 	<li>Seriada Esofagogastroduodenal por doble contraste</li>\n 	<li>Colangiografía</li>\n 	<li>Urograma Extretor</li>\n 	<li>Ecografías: abdominal, hepatobiliopancreática, mamaria, testicular, renal, prostática, partes blandas, obstétricas, pleural, tiroides</li>\n 	<li>Ecodoppler, vasos de cuellos, miembros superiores e inferiores</li>\n 	<li>Laboratorios, completos</li>\n</ul>\n\n<hr />\n\n<h4><strong> Servicios:</strong></h4>\n<ul>\n 	<li>Cardiología Gral.</li>\n 	<li>Cardiología Infantil</li>\n 	<li>Cardiología Riesgo Quirúrgico</li>\n 	<li>Cirugía Cuello y Cabeza</li>\n 	<li>Cirugía Traumatológica de Rodilla</li>\n 	<li>Cirugía General</li>\n 	<li>Cirugía Plástica</li>\n 	<li>Cirugía Vascular</li>\n 	<li>Clínica Medica</li>\n 	<li>Curaciones</li>\n 	<li>Dermatología Gral.</li>\n 	<li>Dermatología Infantil</li>\n 	<li>Diabetes</li>\n 	<li>Eco cardiogramas</li>\n 	<li>Ecocardio Dopler</li>\n 	<li>Ecodopler Periférico</li>\n 	<li>Endocrinología</li>\n 	<li>Ergometrías</li>\n 	<li>Espirómetros</li>\n 	<li>Fonoaudiología</li>\n 	<li>Gastroenterología</li>\n 	<li>Ginecología adolescente</li>\n 	<li>Ginecología Gral.</li>\n 	<li>Hematología</li>\n 	<li>Holter 24 hs.</li>\n 	<li>Infectologia</li>\n 	<li>Infectologia infantil</li>\n 	<li>Maternidad</li>\n 	<li>Nefrología</li>\n 	<li>Neurocirugía</li>\n 	<li>Neurología</li>\n 	<li>Nutrición</li>\n 	<li>Otorrinolaringología</li>\n 	<li>Odontología</li>\n 	<li>Oftalmología</li>\n 	<li>Oncología</li>\n 	<li>Pediatría</li>\n 	<li>Psicología</li>\n 	<li>Psiquiatría</li>\n 	<li>Reumatología</li>\n 	<li>Traumatología</li>\n 	<li>Urología</li>\n 	<li>Vías Respiratorias Adultos</li>\n 	<li>Vias respiratorias Infantil</li>\n</ul>','Hospital Dr. Raúl F. Larcade','','publish','open','open','','hospital-lacarde-servicios-y-estudios-2','','','2025-05-17 22:19:20','2025-05-17 22:19:20','',0,'http://msm-dev.local/centros-salud/hospital-lacarde-servicios-y-estudios-2/',0,'centros_salud','',0);
