p:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"http://msm-dev.local/wp-content/uploads/2025/05/3.5.-bis-Ejecucion-de-Gastos-PArtida-Principal-y-hasta-obras.pdf\" title=\"\">3.5. bis Ejecución de Gastos - PArtida Principal y hasta obras.pdf</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"http://msm-dev.local/wp-content/uploads/2025/05/4.1-Estado-de-finalidad-y-funcion.pdf\" title=\"\">4.1. Estado de finalidad y función.pdf</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"http://msm-dev.local/wp-content/uploads/2025/05/05.01-STOCK-DE-DEUDA-Y-PERFIL-DE-VENCIMIENTOS-Planilla-Modelo-31-03-2025.pdf\" title=\"\">5.1. Stock de deuda y perfil de vencimientos - Planilla Modelo 31-03-2025.pdf</a></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Segundo Trimestre</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><a href=\"http://msm-dev.local/wp-content/uploads/2025/10/1Fiscal-e-Impositiva-2025-registrada.pdf\" title=\"\">1. Fiscal e Impositiva 2025 registrada</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"http://msm-dev.local/wp-content/uploads/2025/10/1.2.-Prespuesto-de-Gastos-Aprobado-2025-Partida-Principal.pdf\" title=\"\">1.2. Prespuesto de Gastos Aprobado 2025 - Partida Principal</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"http://msm-dev.local/wp-content/uploads/2025/10/3.1-Estado-de-Ejecucion-del-Calculo-de-Recursos-por-Procedencia-2do-Trimestre-2025.pdf\" title=\"\">3.1 Estado de Ejecución del Calculo de Recursos por Procedencia 2do Trimestre 2025</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"http://msm-dev.local/wp-content/uploads/2025/10/3.2-Estado-de-Ejecucion-del-Calculo-de-Recursos-por-Caracter-Economico-2do-Trimestre-2025.pdf\" title=\"\">3.2 Estado de Ejecución del Calculo de Recursos por Caracter Economico 2do Trimestre 2025</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"http://msm-dev.local/wp-content/uploads/2025/10/3.4-Estado-de-Ejecucion-de-Gastos-por-Objeto-2do-Trimestre-2025.pdf\" title=\"\">3.4 Estado de Ejecución de Gastos por Objeto 2do Trimestre 2025</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"http://msm-dev.local/wp-content/uploads/2025/10/3.5-Estado-de-Ejecucion-de-Gastos-por-Objeto-2do-Trimestre-2025.pdf\" title=\"\">3.5 Estado de Ejecución de Gastos por Objeto 2do Trimestre 2025</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"http://msm-dev.local/wp-content/uploads/2025/10/3.5-BIS-Estado-de-Ejecucion-de-Gastos-por-Objeto-gasta-programa-2do-Trimestre-2025.pdf\" title=\"\">3.5 BIS Estado de Ejecución de Gastos por Objeto gasta programa 2do Trimestre 2025</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"http://msm-dev.local/wp-content/uploads/2025/10/4.1-Estado-de-Ejecucion-de-Gastos-por-Finalidad-y-Funcion-2do-Trimestre-2025.pdf\" title=\"\">4.1 Estado de Ejecución de Gastos por Finalidad y Función 2do Trimestre 2025</a></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Tercer Trimestre</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><a href=\"http://msm-dev.local/wp-content/uploads/2025/10/1Fiscal-e-Impositiva-2025-registrada-1.pdf\" title=\"\">1. Fiscal e Impositiva 2025 registrada</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"http://msm-dev.local/wp-content/uploads/2025/10/1.2.-Prespuesto-de-Gastos-Aprobado-2025-Partida-Principal-1.pdf\" title=\"\">1.2. Prespuesto de Gastos Aprobado 2025 - Partida Principal</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"http://msm-dev.local/wp-content/uploads/2025/10/3.1-Estado-de-Ejecucion-del-Calculo-de-Recu