INSERT INTO `wp_posts` VALUES (2938,1,'2025-05-29 01:20:06','2025-05-29 01:20:06','<!-- wp:html -->\n<h1 class=\"mb-2\">Encabezado H1 – Título principal</h1>\n<h2 class=\"mb-2\">Encabezado H2 – Sección</h2>\n<h3 class=\"mb-2\">Encabezado H3 – Subsección</h3>\n<h4 class=\"mb-2\">Encabezado H4 – Detalle</h4>\n<h5 class=\"mb-2\">Encabezado H5 – Nota o subdetalle</h5>\n<h6 class=\"mb-4\">Encabezado H6 – Anotación mínima</h6>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<h2 class=\"fz-28 fw-bold mb-3\">Cómo solicitar un Permiso de Obra</h2>\n<p class=\"fz-18 text-secondary mb-4\">Guía paso a paso para iniciar el trámite desde casa</p>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<a href=\"#\"  class=\"btn btn-primary mb-4 text-white text-decoration-none\">Iniciar trámite</a>\n\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<div class=\"alert alert-primary p-3 mb-4\" role=\"alert\">\n  <strong>Recordá:</strong> Todos los documentos deben ser presentados en formato PDF y firmados digitalmente.\n</div>\n\n<div class=\"alert alert-info mb-5 px-5 py-4\" role=\"alert\">\n  <h4>¿Cuáles son los requisitos?</h4>\n  <p class=\"mb-0\">Texto más extenso de requisitos.</p>\n</div>\n\n<div class=\"alert alert-primary p-3 mb-4\" role=\"alert\">\n  <p class=\"fz-16 text-secondary mb-0\">Una alerta primaria simple—¡revisá los detalles!</p>\n</div>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<div class=\"card p-4 mb-4\">\n  <h4 class=\"fz-20 fw-600\">Permiso Unifamiliar</h4>\n  <p class=\"fz-16 text-secondary mb-0\">Vivienda individual de hasta 150m². Plazo estimado: 10 días hábiles.</p>\n</div>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<details class=\"my-4\">\n  <summary class=\"fz-22 fw-600 cursor-pointer\">¿Qué documentación necesito?</summary>\n  <ul class=\"mt-3\">\n    <li class=\"d-flex align-items-center mb-2\">\n      Plano aprobado\n    </li>\n    <li class=\"d-flex align-items-center mb-2\">\n      Copia de DNI\n    </li>\n    <li class=\"d-flex align-items-center mb-2\">\n      Comprobante de pago\n    </li>\n  </ul>\n</details>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<h4 class=\"mb-3\">Permiso de obra nueva</h4>\n<div class=\"d-flex flex-wrap gap-3 my-4\">\n  <div class=\"card-tramite d-flex border rounded overflow-hidden\" style=\"min-width: 320px;\">\n    <div style=\"width: 24px; background-color: #00B6ED;\"></div>\n    <div class=\"p-3\">\n      <h4 class=\"mb-1 fw-600 fz-18\">Unifamiliar</h4>\n      <p class=\"mb-0 text-secondary fz-16\">Destinada a vivienda unifamiliar.</p>\n    </div>\n  </div>\n\n  <div class=\"card-tramite d-flex border rounded overflow-hidden\" style=\"min-width: 320px;\">\n    <div style=\"width: 24px; background-color: #00B6ED;\"></div>\n    <div class=\"p-3\">\n      <h4 class=\"mb-1 fw-600 fz-18\">Multifamiliar</h4>\n      <p class=\"mb-0 text-secondary fz-16\">Destinada a vivienda multifamiliar.</p>\n    </div>\n  </div>\n</div>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<hr class=\"my-4\" style=\"border-top: 1px solid #ccc;\">\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<blockquote class=\"border-start border-4 ps-3 text-muted fst-italic my-4\">\n  \"La gestión municipal comienza con la escucha atenta.\"\n</blockquote>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<span class=\"badge bg-primary text-white px-2 py-1 rounded-pill\">Nuevo</span>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<div class=\"alerta alerta-success p-3 my-3\">\n  <strong>TIP:</strong> Podés hacer este trámite online sin turno previo.\n</div>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<div class=\"d-flex flex-wrap gap-4 my-4\">\n  <div class=\"text-center\" style=\"width: 120px;\">\n    <img src=\"/wp-content/themes/msm-theme/assets/images/icons/salud.svg\" width=\"40\" alt=\"Salud\">\n    <p class=\"mt-2 fz-14\">Salud</p>\n  </div>\n  <div class=\"text-center\" style=\"width: 120px;\">\n    <img src=\"/wp-content/themes/msm-theme/assets/images/icons/educacion.svg\" width=\"40\" alt=\"Educación\">\n    <p class=\"mt-2 fz-14\">Educación</p>\n  </div>\n</div>\n<!-- /wp:html -->\n<!-- wp:html -->\n<table class=\"table table-bordered table-hover my-4\">\n  <thead class=\"table-secondary\">\n    <tr>\n      <th scope=\"col\" class=\"fw-semibold fs-5 text-dark\">Requisito</th>\n      <th scope=\"col\" class=\"fw-semibold fs-5 text-dark\">Obligatorio</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td class=\"fw-normal fs-6 text-body\">Copia de DNI</td>\n      <td class=\"fw-normal fs-6 text-body\">Sí</td>\n    </tr>\n    <tr>\n      <td class=\"fw-normal fs-6 text-body\">Plano firmado</td>\n      <td class=\"fw-normal fs-6 text-body\">Sí</td>\n    </tr>\n  </tbody>\n</table>\n<!-- /wp:html -->\n\n\n\n\n<!-- wp:html -->\n<a href=\"#\" class=\"d-inline-block fw-bold text-decoration-underline text-primary fz-16 my-2\">\n  Ver requisitos completos →\n</a>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<div class=\"componente-demo my-5\">\n  <h3 class=\"mb-2\">🔘 Botón primario</h3>\n  <p class=\"text-muted\">Usalo para acciones principales como iniciar un trámite.</p>\n\n  <!-- VISTA RENDERIZADA -->\n  <div class=\"preview mb-3\">\n    <a href=\"#\" class=\"btn btn-primary text-white text-decoration-none\" role=\"button\">Iniciar trámite</a>\n  </div>\n\n  <!-- CÓDIGO PARA COPIAR -->\n  <pre class=\"bg-light border rounded p-3 small\"><code>&lt;a href=\"#\" class=\"btn btn-primary\"&gt;Iniciar trámite&lt;/a&gt;</code></pre>\n</div>\n<!-- /wp:html -->\n\n<h3>Shortcodes Cards</h3>\n\n<!-- wp:html -->\n[msm_card \n title=\"Empleo Joven\"\n desc=\"Programas para jóvenes de 18 a 24 años con orientación y capacitaciones.\"\n link=\"https://tusitio.com/programa/empleo-joven\"\n variant=\"2\"\n height=\"220px\"]\n\n\n[msm_card \n title=\"Portal de Empleo\"\n link=\"/portal-empleo\"\n variant=\"1\"]\n<!-- /wp:html -->\n\n\n\n\n[msm_card \n title=\"Unifamiliar\"\n desc=\"Destinada a vivienda unifamiliar.\"\n link=\"#\"\n variant=\"1\"]\n[msm_card \n title=\"Unifamiliar\"\n desc=\"Destinada a vivienda unifamiliar.\"\n link=\"#\"\n variant=\"2\"]\n\n\n\n\n\n\n <div class=\"row mb-5\">\n      <div class=\"col-6\">\n         [msm_card \n title=\"Unifamiliar\"\n desc=\"Destinada a vivienda unifamiliar.\"\n link=\"#\"\n variant=\"3\"]\n      </div>\n      <div class=\"col-6\">\n        [msm_card \n title=\"Multifamiliar\"\n desc=\"Destinada a vivienda unifamiliar.\"\n link=\"#\"\n variant=\"3\"]\n      </div>      \n    </div>\n  <!-- /wp:post-content -->\n','Guía de estilos para contenidos','Guía de estilo de componentes para el contenido del sitio, html y otros elementos con estilo.','publish','open','open','','guia-de-estilos-para-contenidos','','','2025-06-01 00:58:47','2025-06-01 00:58:47','',0,'http:/prensa//prensa/msm-dev.local/prensa/?p=2938',0,'post','',0);
INSERT INTO `wp_posts` VALUES (2939,1,'2025-05-29 01:20:06','2025-05-29 01:20:06','<!-- wp:paragraph -->\n<p><a href=\"#\">Ver más</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<div class=\"alerta alerta-info p-3 my-3\">\n  <strong>Importante:</strong> Recordá presentar los documentos en formato PDF.\n</div>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<div class=\"card-tramite p-3 my-2\">\n  <h4 class=\"fz-20 fw-600\">Unifamiliar</h4>\n  <p class=\"fz-16 text-secondary\">Destinada a vivienda unifamiliar.</p>\n</div>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<details class=\"my-3\">\n  <summary class=\"fz-18 fw-600 cursor-pointer\">¿Qué documentación necesito?</summary>\n  <p class=\"mt-2\">Debés presentar planos firmados, DNI y comprobante de pago.</p>\n</details>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<ul class=\"list-unstyled my-3\">\n  <li class=\"d-flex align-items-center mb-2\">\n    <img src=\"/wp-content/themes/tu-theme/assets/images/icons/check.svg\" alt=\"\" width=\"20\" class=\"me-2\">\n    Permiso de obra nueva\n  </li>\n  <li class=\"d-flex align-items-center mb-2\">\n    <img src=\"/wp-content/themes/tu-theme/assets/images/icons/check.svg\" alt=\"\" width=\"20\" class=\"me-2\">\n    Informe de inspección\n  </li>\n</ul>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Guía de estilos para contenidos','','inherit','closed','closed','','2938-revision-v1','','','2025-05-29 01:20:06','2025-05-29 01:20:06','',2938,'http://msm-dev.local/?p=2939',0,'revision','',0);
